package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.backup.*;
import cn.mop.domain.backup.BackupPlanDraftRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Isolated boundaries only; actual PG/OIDC/CSRF HTTP checks are separate. */
class BackupPlanDraftControllerTest {
    static final String ACTOR="76000000-0000-4000-8000-000000000001",TENANT="76000000-0000-4000-8000-000000000002",ID="76000000-0000-4000-8000-000000000003",ASSET="76000000-0000-4000-8000-000000000004",OTHER="76000000-0000-4000-8000-000000000005";
    PlatformRepository platform;BackupPlanDraftRepository plans;BackupPlanDraftController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);plans=mock(BackupPlanDraftRepository.class);controller=new BackupPlanDraftController(platform,plans);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true)));when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(call->{((Runnable)call.getArgument(6)).run();return ((Supplier<?>)call.getArgument(7)).get();});when(plans.create(any(),any())).thenAnswer(call->row(1,false,call.getArgument(1)));when(plans.update(any(),any(),anyLong(),any())).thenAnswer(call->row(2,false,call.getArgument(3)));when(plans.archive(any(),any(),anyLong())).thenReturn(row(2,true,draft()));when(plans.restore(any(),any(),anyLong())).thenReturn(row(3,false,draft()));}
    Access access(){return new Access(ACTOR,TENANT,7,"backup-plan-test");}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/backup-plan-drafts");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","backup-plan-test");r.addHeader("Idempotency-Key","backup-plan-test-key");return r;}
    BackupPlanDraft draft(){return new BackupPlanDraft(UUID.fromString(TENANT),"合成备份草稿",List.of(UUID.fromString(ASSET)),"02:00",null,true,null);}
    Snapshot row(long version,boolean archived,BackupPlanDraft d){var t=Instant.parse("2026-10-04T08:00:00.123Z");return new Snapshot(ID,TENANT,version,d,archived,ACTOR,t,t,t);}
    ObjectNode input(){var n=mapper.createObjectNode().put("expected_version",0).put("name","合成备份草稿").put("daily_local_time","02:00").putNull("credential_ref").put("requested_enabled",true).putNull("note");n.putArray("target_asset_ids").add(ASSET);return n;}
    static Map<?,?> data(Object r){return (Map<?,?>)((Map<?,?>)r).get("data");}
    @Test void createProjectsTenantFromSessionAndNeverEnablesIntent(){var out=data(controller.write(null,"CREATE",input(),request("POST")));assertEquals(TENANT,out.get("tenant_id"));assertEquals(true,out.get("requested_enabled"));assertEquals(false,out.get("enabled"));assertEquals(false,out.get("effective"));assertEquals(false,out.get("device_execution_allowed"));assertNull(out.get("next_execution_at"));assertEquals("NOT_SUPPLIED",out.get("credential_verification"));verify(plans).authorizeCurrentAccess(access(),null);verify(plans).create(access(),draft());}
    @Test void unknownTenantExecutionAndSecretFieldsAreRejected(){for(String field:List.of("tenant_id","enabled","effective","command","password","access_key","approved")){var n=input().put(field,"SYNTHETIC_SECRET");assertEquals(400,assertThrows(DomainException.class,()->controller.write(null,"CREATE",n,request("POST"))).status);}verify(plans,never()).create(any(),any());}
    @Test void allInputFieldsIncludingExplicitNullsAndIntentAreRequired(){for(String f:List.of("expected_version","name","target_asset_ids","daily_local_time","credential_ref","requested_enabled","note")){var n=input();n.remove(f);assertThrows(DomainException.class,()->controller.write(null,"CREATE",n,request("POST")));}}
    @Test void inputTypesDuplicatesAndStrictClockFailBeforeWrite(){for(var value:List.of(input().put("requested_enabled","true"),input().put("credential_ref","not-a-uuid"),input().put("daily_local_time","2:00"),input().put("note",3),input().put("name","\u00a0"),input().put("expected_version",0.0))){assertThrows(DomainException.class,()->controller.write(null,"CREATE",value,request("POST")));}var duplicate=input();duplicate.withArray("target_asset_ids").add(ASSET);assertThrows(DomainException.class,()->controller.write(null,"CREATE",duplicate,request("POST")));var empty=input();empty.withArray("target_asset_ids").removeAll();assertThrows(DomainException.class,()->controller.write(null,"CREATE",empty,request("POST")));}
    @Test void targetLimitAndUnicodeBoundsDoNotTruncate(){var huge=input();for(int i=0;i<1000;i++)huge.withArray("target_asset_ids").add(new UUID(2,i).toString());assertThrows(DomainException.class,()->controller.write(null,"CREATE",huge,request("POST")));assertThrows(DomainException.class,()->controller.write(null,"CREATE",input().put("note","😀".repeat(4001)),request("POST")));var okay=input().put("name","😀".repeat(100)).put("note","😀".repeat(4000));assertEquals("😀".repeat(4000),data(controller.write(null,"CREATE",okay,request("POST"))).get("note"));}
    @Test void updateRequiresPositiveBoundedExpectedVersion(){for(long n:new long[]{-1,0,9007199254740990L})assertThrows(DomainException.class,()->controller.write(ID,"UPDATE",input().put("expected_version",n),request("PATCH")));var out=data(controller.write(ID,"UPDATE",input().put("expected_version",1),request("PATCH")));assertEquals(2L,out.get("version"));verify(plans).update(access(),ID,1,draft());}
    @Test void archiveAndRestoreAcceptVersionOnlyAndCannotChangeDefinition(){for(String action:List.of("ARCHIVE","RESTORE")){assertThrows(DomainException.class,()->controller.write(ID,action,input().put("expected_version",1),request("POST")));controller.write(ID,action,mapper.createObjectNode().put("expected_version",1),request("POST"));}verify(plans).archive(access(),ID,1);verify(plans).restore(access(),ID,1);}
    @Test void replayCallsAuthorizationAndReturnsOriginalWithoutExecutingAgain(){doAnswer(call->{((Runnable)call.getArgument(6)).run();return Map.of("original",true);}).when(platform).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());assertEquals(true,data(controller.write(ID,"ARCHIVE",mapper.createObjectNode().put("expected_version",1),request("POST"))).get("original"));verify(plans).authorizeCurrentAccess(access(),ID);verify(plans,never()).archive(any(),any(),anyLong());}
    @Test void hashIgnoresObjectKeyOrderButBindsTargetOrderNullAndExpectedVersion(){var a=input();a.withArray("target_asset_ids").add(OTHER);var reordered=mapper.createObjectNode();var keys=new ArrayList<String>();a.fieldNames().forEachRemaining(keys::add);Collections.reverse(keys);for(String k:keys)reordered.set(k,a.get(k));controller.write(null,"CREATE",a,request("POST"));controller.write(null,"CREATE",reordered,request("POST"));var changed=a.deepCopy();changed.withArray("target_asset_ids").removeAll().add(OTHER).add(ASSET);controller.write(null,"CREATE",changed,request("POST"));controller.write(null,"CREATE",a.deepCopy().put("note",""),request("POST"));controller.write(ID,"UPDATE",a.deepCopy().put("expected_version",1),request("PATCH"));var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(5)).idempotentAuthorized(any(),any(),any(),any(),hashes.capture(),anyLong(),any(),any());var h=hashes.getAllValues();assertEquals(h.get(0),h.get(1));for(int i=2;i<5;i++)assertNotEquals(h.get(0),h.get(i));}
    @Test void listReturnsMetadataOnlyAndPairedBoundedCursor(){when(plans.list(eq(access()),eq(16),isNull(),isNull())).thenReturn(Collections.nCopies(16,row(1,false,draft())));var out=data(controller.list(request("GET")));assertEquals(true,out.get("has_more"));assertEquals(20,out.get("page_size_limit"));var items=(List<?>)out.get("items");assertEquals(15,items.size());assertFalse(((Map<?,?>)items.get(0)).containsKey("target_asset_ids"));assertFalse(((Map<?,?>)items.get(0)).containsKey("note"));assertEquals(ID,out.get("next_before_id"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void getAndHistoryReturnUnpublishedExplicitTargets(){when(plans.get(access(),ID)).thenReturn(row(1,false,draft()));assertEquals(List.of(ASSET),data(controller.get(ID,request("GET"))).get("target_asset_ids"));var t=Instant.parse("2026-10-04T08:00:00Z");when(plans.history(access(),ID,16,null)).thenReturn(List.of(new Revision(ID,TENANT,1,"CREATE",draft(),false,ACTOR,t)));var out=data(controller.history(ID,request("GET")));assertNull(out.get("next_before_version"));var item=(Map<?,?>)((List<?>)out.get("items")).get(0);assertNull(item.get("previous_version"));assertEquals(false,item.get("enabled"));}
    @Test void queryDuplicatesUnknownKeysAndInvalidPageSizesAreRejected(){for(String key:List.of("tenant_id","enabled","execute")){var r=request("GET");r.addParameter(key,"true");assertThrows(DomainException.class,()->controller.list(r));}var duplicate=request("GET");duplicate.addParameter("page_size","10","15");assertThrows(DomainException.class,()->controller.list(duplicate));for(String size:List.of("1","100","20.0","01")){var r=request("GET");r.addParameter("page_size",size);assertThrows(DomainException.class,()->controller.list(r));}var half=request("GET");half.addParameter("before_id",ID);assertThrows(DomainException.class,()->controller.list(half));}
    @Test void mutationsRejectAnyQueryOrMissingIdempotencyKey(){var q=request("POST");q.addParameter("dry_run","true");assertThrows(DomainException.class,()->controller.write(null,"CREATE",input(),q));var noKey=request("POST");noKey.removeHeader("Idempotency-Key");assertThrows(DomainException.class,()->controller.write(null,"CREATE",input(),noKey));}
    @Test void currentRoleAndSessionGatePrecedePayloadParsing(){for(String role:List.of("viewer","msp","tadmin","unknown")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));var r=request("POST");r.setContent("{bad".getBytes(StandardCharsets.UTF_8));assertEquals(403,assertThrows(DomainException.class,()->controller.create(r)).status);}var anonymous=new MockHttpServletRequest();assertEquals(401,assertThrows(DomainException.class,()->controller.list(anonymous)).status);verifyNoInteractions(plans);}
    @Test void bodyRejectsDuplicateKeysTrailingDocumentsAndDeepNesting(){for(String s:List.of("{\"expected_version\":0,\"expected_version\":1}","{}{}","{\"a\":{\"b\":{\"c\":{\"d\":{\"e\":1}}}}}")){var r=request("POST");r.setContent(s.getBytes(StandardCharsets.UTF_8));assertEquals(400,assertThrows(DomainException.class,()->BackupPlanDraftController.body(r)).status);}}
    @Test void bodyByteAndTokenLimitsAre413WithoutTruncation(){var r=request("POST");r.setContent(new byte[BackupPlanDraftController.MAX_BODY_BYTES+1]);assertEquals(413,assertThrows(DomainException.class,()->BackupPlanDraftController.body(r)).status);var token=request("POST");token.setContent(("["+"null,".repeat(4000)+"null]").getBytes(StandardCharsets.UTF_8));assertEquals(413,assertThrows(DomainException.class,()->BackupPlanDraftController.body(token)).status);var streamed=new MockHttpServletRequest(){@Override public long getContentLengthLong(){return -1;}};streamed.setContent(new byte[BackupPlanDraftController.MAX_BODY_BYTES+1]);assertEquals(413,assertThrows(DomainException.class,()->BackupPlanDraftController.body(streamed)).status);}
    @Test void validRawBodyKeepsNullAndWhitespace(){var n=input().put("note"," \n\t😀 ");var r=request("POST");r.setContent(n.toString().getBytes(StandardCharsets.UTF_8));assertEquals(n,BackupPlanDraftController.body(r));var fresh=request("POST");fresh.setContent(n.toString().getBytes(StandardCharsets.UTF_8));assertEquals(" \n\t😀 ",data(controller.create(fresh)).get("note"));}
    @Test void opaqueCredentialReferenceRemainsUnverifiedAndDoesNotExposeASecretField(){var n=input().put("credential_ref",OTHER);var out=data(controller.write(null,"CREATE",n,request("POST")));assertEquals(OTHER,out.get("credential_ref"));assertEquals("NOT_VERIFIED_BY_THIS_MODEL",out.get("credential_verification"));assertFalse(out.containsKey("password"));assertEquals("CONTRACT_CONFIGURABLE_DEFAULT_NOT_EFFECTIVE",out.get("retry_policy_source"));}
    @Test void schedulePreviewBindsExplicitDateVersionAndKeepsExecutionDisabled(){
        when(plans.get(access(),ID)).thenReturn(row(1,false,draft()));var r=request("GET");r.addParameter("date","2026-10-22");r.addParameter("expected_version","1");
        var out=data(controller.schedulePreview(ID,r));assertEquals("2026-10-21T18:00:00Z",out.get("candidate_instant"));assertEquals("2026-10-22T02:00",out.get("requested_local_date_time"));
        assertEquals("UNPUBLISHED_CALENDAR_CANDIDATE",out.get("resolution"));for(String key:List.of("enabled","effective","creates_run","execution_authorized"))assertEquals(false,out.get(key));assertNull(out.get("next_execution_at"));assertNull(out.get("missed_run_policy"));verify(plans).get(access(),ID);verifyNoMoreInteractions(plans);
    }
    @Test void schedulePreviewRejectsStaleVersionWithoutChoosingLatest(){
        when(plans.get(access(),ID)).thenReturn(row(2,false,draft()));var r=request("GET");r.addParameter("date","2026-10-22");r.addParameter("expected_version","1");assertEquals(409,assertThrows(DomainException.class,()->controller.schedulePreview(ID,r)).status);
    }
    @Test void schedulePreviewRequiresCanonicalDateAndBothParameters(){
        for(String date:List.of("2026-02-30","0000-01-01","2026-1-1","today","2026-10-22T00:00:00Z")){var r=request("GET");r.addParameter("date",date);r.addParameter("expected_version","1");assertEquals(400,assertThrows(DomainException.class,()->controller.schedulePreview(ID,r)).status);}
        var absent=request("GET");assertEquals(400,assertThrows(DomainException.class,()->controller.schedulePreview(ID,absent)).status);verifyNoInteractions(plans);
    }
    @Test void schedulePreviewRejectsOverridesDuplicatesAndForeignProjection(){
        var r=request("GET");r.addParameter("date","2026-10-22");r.addParameter("expected_version","1");r.addParameter("tenant_id",OTHER);assertThrows(DomainException.class,()->controller.schedulePreview(ID,r));
        var duplicate=request("GET");duplicate.addParameter("date","2026-10-22","2026-10-23");duplicate.addParameter("expected_version","1");assertThrows(DomainException.class,()->controller.schedulePreview(ID,duplicate));
        var valid=request("GET");valid.addParameter("date","2026-10-22");valid.addParameter("expected_version","1");var t=Instant.parse("2026-10-04T08:00:00Z");when(plans.get(access(),ID)).thenReturn(new Snapshot(ID,OTHER,1,draft(),false,ACTOR,t,t,t));assertEquals(503,assertThrows(DomainException.class,()->controller.schedulePreview(ID,valid)).status);
    }
    @Test void archivedPreviewIsCalendarOnlyAndHeadersArePrivate(){
        when(plans.get(access(),ID)).thenReturn(row(2,true,draft()));var r=request("GET");r.addParameter("date","2026-10-22");r.addParameter("expected_version","2");var out=data(controller.schedulePreview(ID,r));assertEquals(true,out.get("archived"));assertEquals(false,out.get("creates_run"));var response=new org.springframework.mock.web.MockHttpServletResponse();controller.privateHeaders(response);assertEquals("no-store",response.getHeader("Cache-Control"));assertEquals("no-referrer",response.getHeader("Referrer-Policy"));
    }
}
